package com.peppeosmio.lockate.anonymous_group.entity;

import com.peppeosmio.lockate.common.classes.EncryptedString;
import jakarta.persistence.*;
import java.time.LocalDateTime;
import java.util.UUID;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import org.hibernate.annotations.OnDelete;
import org.hibernate.annotations.OnDeleteAction;

@Entity
@Table(
    name = "ag_circle",
    indexes = {@Index(name = "idx_ag_circle_group_id", columnList = "anonymous_group_id")})
@Getter
@Setter
@NoArgsConstructor
public class AGCircleEntity {

  // Generated by the client: it is part of the AAD of the encrypted data
  @Id
  @Column(name = "id")
  private UUID id;

  @Column(name = "data_cipher", nullable = false)
  private byte[] dataCipher;

  @Column(name = "data_iv", nullable = false)
  private byte[] dataIv;

  @Column(name = "created_at", nullable = false)
  private LocalDateTime createdAt;

  @Column(name = "updated_at", nullable = false)
  private LocalDateTime updatedAt;

  @Column(name = "anonymous_group_id", nullable = false, insertable = false, updatable = false)
  private UUID anonymousGroupId;

  @ManyToOne(optional = false, fetch = FetchType.LAZY)
  @JoinColumn(name = "anonymous_group_id", nullable = false)
  @OnDelete(action = OnDeleteAction.CASCADE)
  private AnonymousGroupEntity anonymousGroupEntity;

  public AGCircleEntity(
      UUID id,
      EncryptedString encryptedData,
      AnonymousGroupEntity anonymousGroupEntity,
      LocalDateTime now) {
    this.id = id;
    this.dataCipher = encryptedData.cipherText();
    this.dataIv = encryptedData.iv();
    this.anonymousGroupEntity = anonymousGroupEntity;
    this.anonymousGroupId = anonymousGroupEntity.getId();
    this.createdAt = now;
    this.updatedAt = now;
  }

  public EncryptedString getEncryptedData() {
    return new EncryptedString(dataCipher, dataIv);
  }

  public void setEncryptedData(EncryptedString encryptedData, LocalDateTime now) {
    this.dataCipher = encryptedData.cipherText();
    this.dataIv = encryptedData.iv();
    this.updatedAt = now;
  }
}
